const products = $input.first().json.products;
if (!Array.isArray(products)) throw new Error('商店目录没有返回商品列表');
const selected = [];
for (const p of products) {
  if (p.product_type !== 'Coffee' || !/^[a-z0-9-]+$/.test(p.handle)) continue;
  const v = p.variants.find(v => v.available && /\b12\s*oz\b/i.test(v.title));
  if (!v) continue;
  selected.push({json: {title:p.title, url:'https://counterculturecoffee.com/products/'+p.handle, price:v.price, size:v.title, image:p.images[0]?.src || ''}, pairedItem:{item:0}});
  if (selected.length === 3) break;
}
if (!selected.length) throw new Error('当前目录没有可售的 12 oz 咖啡');
return selected;

const catalog = $('选出三款在售咖啡').all().map(x=>x.json);
const checked = new Map($input.all().map(x=>[x.json.taskId,x.json]));
const results = new Map($('Nstdata Crawl · 读取商品页').all().map(x=>{
  const initial=x.json, latest=checked.get(initial.taskId);
  return [initial.url,initial.markdown || !latest?.markdown ? initial : latest];
}));
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dict = [
  [/chocolat(e|y)/i,'巧克力'],[/blueberr(y|ies)/i,'蓝莓'],[/marmalade/i,'柑橘果酱'],[/caramel/i,'焦糖'],[/\bnutty\b|hazelnut/i,'坚果'],[/floral/i,'花香'],[/\bcitrus\b/i,'柑橘'],[/stone fruit/i,'核果'],[/molasses/i,'糖蜜'],[/jasmine/i,'茉莉'],[/peach/i,'桃子'],[/black tea/i,'红茶'],[/lemon/i,'柠檬'],[/berry|berries/i,'浆果']
];
function describe(markdown,title) {
  const lines=markdown.split(/\n/).map(s=>s.trim()).filter(s=>s && !s.startsWith('!') && !s.includes('](')).map(s=>s.replace(/^[>#*\s-]+|[*_]/g,'').trim());
  const anchor=lines.findIndex(s=>s.toLowerCase()===title.toLowerCase());
  const scope=(anchor>=0?lines.slice(anchor):lines).slice(0,140);
  const tasting=scope.find(s=>s.length<110 && /\s[•·|]\s/.test(s) && dict.some(([r])=>r.test(s)));
  const descriptive=scope.filter(s=>s.length>65 && !/cookie|shipping|subscribe|add to cart|newsletter|privacy|checkout|function\(/i.test(s));
  const excerpt=descriptive.find(s=>s.toLowerCase().includes(title.toLowerCase()) || /notes of|flavo[u]?rs? of|hints of|coffee(s)? we purchase/i.test(s)) || descriptive[0] || '';
  const tags=dict.filter(([r])=>r.test(tasting || excerpt)).map(x=>x[1]).filter((x,i,a)=>!(x==='浆果' && a.includes('蓝莓'))).slice(0,3);
  const short=excerpt.split(/\s+/).slice(0,17).join(' ');
  return {tags,short:short+(short && short!==excerpt?'…':'')};
}
const stamp=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());
let successes=0;
const cards=catalog.map((p,i)=>{
  const r=results.get(p.url)||{};
  const ok=r.status==='completed' && !!r.markdown?.trim() && !r.error && !(Number(r.metadata?.statusCode)>=400);
  if(ok) successes++;
  const {tags,short}=ok?describe(r.markdown,p.title):{tags:[],short:''};
  const price=Number(p.price);
  const photo=/^https:\/\/cdn\.shopify\.com\//.test(p.image)?p.image:'';
  return `<article><div class="photo">${photo?`<img alt="${esc(p.title)}" src="${esc(photo + (photo.includes('?')?'&':'?')+'width=650')}">`:''}<b class="num">0${i+1}</b></div><div class="body"><div class="product"><h2>${esc(p.title)}</h2><b class="price">${Number.isFinite(price)?'$'+price.toFixed(2):'—'}</b></div><small>${esc(p.size)} · USD</small><div class="notes">${tags.length?tags.map(t=>'<span>'+esc(t)+'</span>').join(''):(ok?'正文未识别出风味词':'本次未取得正文')}</div>${short?'<blockquote lang="en">'+esc(short)+'</blockquote>':''}<footer><span>${ok?'Markdown · '+r.markdown.length.toLocaleString('en-US')+' 字符':(r.timedOut?'等待超时':'抓取未完成')}</span><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">商品原页 ↗</a></footer></div></article>`;
});
const html=`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>咖啡货架观察 · Nstdata Crawl</title><style>
*{box-sizing:border-box}body{margin:0;background:#f9f6ed;color:#1c3028;font-family:"PingFang SC","Microsoft YaHei",Arial,sans-serif}main{max-width:1380px;margin:auto;padding:25px 4.3vw 32px}header,.meta,footer,.product{display:flex;justify-content:space-between;align-items:center;gap:12px}header{padding-bottom:17px;border-bottom:1px solid #abb4a4}header strong{font:700 21px Georgia,serif}header span,.meta,small,footer{font-size:13px;color:#526257}.hero{padding:40px 0 27px}.kicker{letter-spacing:.16em;font-size:12px;color:#8a421f;font-weight:700}h1{font-size:clamp(38px,5.2vw,76px);letter-spacing:-.06em;margin:9px 0}.hero p{font-size:16px;margin:7px 0;color:#4e5f53;line-height:1.65}.meta{border-block:1px solid #b7c0ad;padding:10px 0;margin-bottom:18px;flex-wrap:wrap}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}article{background:#fffefa;border:1px solid #d6d9c9;display:flex;flex-direction:column}.photo{position:relative;height:clamp(165px,18vw,235px);overflow:hidden;background:#f1efe7}.photo img{width:100%;height:100%;object-fit:contain;display:block}.num{position:absolute;top:12px;left:12px;color:white;background:#243a32;padding:5px 9px;font:13px Georgia,serif}.body{padding:17px 18px 12px;flex:1;display:flex;flex-direction:column}.product{align-items:baseline}h2{font:600 clamp(21px,2.2vw,32px)/1.05 Georgia,serif;margin:0}.price{white-space:nowrap}.body small{margin:8px 0 14px}.notes{min-height:25px;font-size:13px;color:#61705a}.notes span{display:inline-block;background:#eaf0e0;color:#345039;border-radius:4px;padding:4px 8px;margin:0 5px 4px 0}blockquote{font:italic 15px/1.45 Georgia,serif;margin:12px 0 18px;color:#435344}footer{border-top:1px solid #e1e2d8;padding-top:11px;margin-top:auto;font-size:11px}footer a{color:#284d39;font-weight:700}.credit{font-size:12px;line-height:1.7;color:#5f6a5c;margin:16px 0 0}@media(max-width:740px){.grid{grid-template-columns:1fr}.photo{height:225px}.hero{padding-top:24px}.meta{gap:4px}header span{font-size:11px}}
</style><main><header><strong>Nstdata Crawl</strong><span>零售观察 &nbsp; / &nbsp; 咖啡</span></header><section class="hero"><div class="kicker">COUNTER CULTURE COFFEE</div><h1>咖啡货架观察</h1><p>今天店里有哪些 12 oz 咖啡？看一眼价格，再从商品正文里读出风味。</p></section><div class="meta"><span>美国商店 · 在售目录前 ${catalog.length} 款符合条件的咖啡</span><span>北京时间 ${esc(stamp)} &nbsp; · &nbsp; 已取得 ${successes}/${catalog.length} 篇正文</span></div><section class="grid">${cards.join('')}</section><p class="credit">商品图片、规格和美元标价来自品牌公开目录。风味词和英文摘录取自 Nstdata 本次读取的商品页 Markdown。价格以店铺结算页为准。</p></main></html>`;
const rows = catalog.map(p => {
  const result = results.get(p.url) || {};
  const ok = result.status === 'completed' && !!result.markdown?.trim() && !result.error && !(Number(result.metadata?.statusCode) >= 400);
  const tags = ok ? describe(result.markdown, p.title).tags : [];
  const tasting = tags.join('、') || (ok ? '未识别出风味词' : '本次未取得正文');
  const url = esc(p.url);
  const title = esc(p.title);
  const photo = /^https:\/\/cdn\.shopify\.com\//.test(p.image) ? p.image : '';
  const thumbnail = photo ? `<a href="${url}"><img src="${esc(photo + (photo.includes('?') ? '&' : '?') + 'width=260')}" alt="${title} 商品图" width="104" style="display:block;width:104px;max-width:100%;height:auto;border:0"></a>` : '';
  return `<tr><td width="112" valign="middle" style="width:112px;padding:12px 8px 12px 0;border-bottom:1px solid #dcded2">${thumbnail}</td><td valign="middle" style="padding:12px 0 12px 8px;border-bottom:1px solid #dcded2"><a href="${url}" style="font: bold 20px Georgia,serif;color:#255b45">${title}</a><br><span style="font-size:14px;color:#273b2f">USD $${esc(p.price)} · ${esc(p.size)}</span><br><span style="font-size:14px;color:#4e6351">${esc(tasting)}</span></td></tr>`;
}).join('');
const emailHtml = `<div style="max-width:580px;margin:auto;font:15px/1.6 Arial,sans-serif;color:#223b31"><p style="color:#566950">Nstdata Crawl · Counter Culture Coffee</p><h2 style="margin-bottom:4px">咖啡货架观察</h2><p>北京时间 ${esc(stamp)}，本次入选 ${catalog.length} 款在售咖啡，取得 ${successes} 篇商品正文。</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse">${rows}</table><p style="font-size:13px">点击图片或商品名可查看原页。完整简报见附件 coffee-shelf.html。</p></div>`;
return [{json:{html,emailHtml,stamp,pages:catalog.length,successfulPages:successes}}];
